#include <stdlib.h>

#define MAX_URL_LENGTH 256

char* get_url_to_visit(const char* domain, const char* subdomain_prefix) {
    // Check for empty or invalid subdomain
    if (subdomain_prefix == NULL || strlen(subdomain_prefix) == 0) {
        char* result = (char*)malloc(MAX_URL_LENGTH * sizeof(char));
        snprintf(result, MAX_URL_LENGTH, "https://%s", domain);
        return result;
    }

    // Check if the combined URL exceeds MAX_URL_LENGTH
    size_t total_length = strlen("https://") + strlen(subdomain_prefix) + strlen(domain) + 1;
    if (total_length >= MAX_URL_LENGTH) {
        fprintf(stderr, "Error: URL length exceeds maximum allowed.\n");
        return NULL;
    }

    char url[MAX_URL_LENGTH];
    snprintf(url, MAX_URL_LENGTH, "https://%s.%s", subdomain_prefix, domain);
    char* result = (char*)malloc(MAX_URL_LENGTH * sizeof(char));
    strcpy(result, url);
    return result;
}
